INSERT INTO review (review_id, customer_id, performance_id, event_rating, venue_rating, comment_text, created_at) VALUES
  (1, 8, 5, 2, 1, 'Parking near the venue was a nightmare but the concert made up for it. Our seats had a clear view of the stage and the whole crowd was electric. The acoustics in the balcony were muddy but the energy was still amazing.', (NOW() + INTERVAL -51 DAY)),
  (2, 15, 5, 3, 1, 'The stage production and video screens were worth the ticket price alone. A tight setlist, a killer light show, and a crowd that never sat down. The opening act warmed up the room before an unforgettable encore.', (NOW() + INTERVAL -67 DAY)),
  (3, 12, 5, 1, 2, 'Parking near the venue was a nightmare but the concert made up for it. The opening act warmed up the room before an unforgettable encore. The acoustics in the balcony were muddy but the energy was still amazing.', (NOW() + INTERVAL -50 DAY)),
